import{_ as s,l as i,o as a,c as n,v as t,p as d,x as o,d as c,i as l,S as V}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"RISC-V 向量扩展 RVV","description":"","frontmatter":{"title":"RISC-V 向量扩展 RVV","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rvv-vector.md","filePath":"cs/rvv-vector.md","lastUpdated":1789023840000}'),v={name:"cs/rvv-vector.md"};function p(E,e,A,h,_,S){const r=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="risc-v-向量扩展-rvv" tabindex="-1">RISC-V 向量扩展 RVV <a class="header-anchor" href="#risc-v-向量扩展-rvv" aria-label="Permalink to &quot;RISC-V 向量扩展 RVV&quot;">​</a></h1><div class="epigraph"><p>向量长度寄存器让同一条指令在不同实现上打不同条数：软件按 `vl` 剥循环，硬件用自己的 VLEN 切条，不必为 128/256/512 各写一遍。</p><footer>—— 据 RISC-V Vector Extension Specification；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/simd-extensions">上一课</a>的 AVX 宽度写进 ISA 分代。缺口是 <strong>RVV</strong>：<code>vsetvl</code> 设定本次 <code>vl</code>，寄存器是向量寄存器组，实现选定 VLEN。与 Cray 风格向量更近，与定宽 NEON 对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可移植二进制：同一 <code>vadd.vv</code> 在 VLEN=128 与 512 的核上都能跑，软件用 strip-mining 循环 <code>vl = vsetvl(n)</code>。缺口不是再解释 DLP，而是这套 <strong>配置</strong>：SEW（元素宽）、LMUL（寄存器分组）、掩码寄存器 <code>v0</code>。内存：unit-stride、strided、indexed（gather/scatter）。</p><p>尾与掩码：<code>vta</code>/<code>vma</code> 策略决定未用元素是否保留——向量谓词，后课条件码再对照标量谓词。</p><h3 id="rvv-不是「risc-v-的-avx-512」" tabindex="-1">RVV 不是「RISC-V 的 AVX-512」 <a class="header-anchor" href="#rvv-不是「risc-v-的-avx-512」" aria-label="Permalink to &quot;RVV 不是「RISC-V 的 AVX-512」&quot;">​</a></h3><p>没有强制 512 位。把 RVV 当某代 Intel 宽度的克隆，可移植性故事会破。也不把 RVV 写成训练框架的自动代码生成目标——本栏停在 ISA。</p><p><span class="marginnote">RISC-V Vector Spec 是权威。CA:AQA 向量机章节给直觉。本课不背全部向量指令 opcode。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>循环：测剩余 <code>n</code>，<code>vsetvl</code>，向量 load/运算/store，指针与 <code>n</code> 递减。异常：向量访存的页故障元素位置要精确或按规范重启，实现复杂——点名。与 <a href="/cs/fence-instructions">fence</a>：向量访存参与同一内存模型。</p>',11)),(a(),d(V,null,{default:o(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%89%A9%E4%BD%99%E5%85%83%E7%B4%A0%20n%22%5D%20--%3E%20VSET%5B%22vsetvl%20%E2%86%92%20vl%22%5D%0A%20%20VSET%20--%3E%20OP%5B%22%E5%90%91%E9%87%8F%E8%BF%90%E7%AE%97%20vl%20%E6%9D%A1%22%5D%0A%20%20OP%20--%3E%20LOOP%5B%22n%20-%3D%20vl%22%5D%0A%20%20LOOP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8E%8B%E7%BC%A9%E6%98%AF%E6%A0%87%E9%87%8F%E7%A0%81%E5%AF%86%E5%BA%A6%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>DSP 定点：RVV 有整数与饱和变体，对应饱和课。FMA 有向量版。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>压缩指令减少标量循环开销，与 RVV 叠用。页表走访仍是标量特权机制；向量 load 只是多次翻译或页跨越处理。本课钉「可变 VL」这一 RISC-V 选择。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某开源核的 VLEN，不写矩阵扩展（RVV 之外）。不把 autovectorizer bug 当 ISA 定义。</p><p>后课默认：RVV 用 <code>vl</code> 与 VLEN 解耦软件与实现宽度；循环靠 strip-mining。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>vsetvl</code> 设定本次元素数；实现选 VLEN。</li><li>不是定宽 AVX 的改名。</li><li>掩码与尾策略处理短尾与条件。</li><li>出处：RISC-V Vector Extension Spec；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const R=s(v,[["render",p]]);export{u as __pageData,R as default};
